const HTML="<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#090a0b\">\n  <title>CEO Notes | ملاحظات يومية في الإدارة والقيادة</title>\n  <meta name=\"description\" content=\"CEO Notes — أفكار عملية عن القيادة والإدارة والعمل الذكي، في مقالات يومية قصيرة قابلة للتطبيق.\">\n  <link rel=\"canonical\" href=\"https://ceo-notes.pages.dev/\">\n  <link rel=\"alternate\" type=\"application/rss+xml\" title=\"CEO Notes RSS\" href=\"https://ceo-notes.pages.dev/rss.xml\">\n  <meta name=\"robots\" content=\"index,follow\">\n  <meta property=\"og:type\" content=\"website\">\n  <meta property=\"og:title\" content=\"CEO Notes | ملاحظات يومية في الإدارة والقيادة\">\n  <meta property=\"og:description\" content=\"أفكار عملية عن القيادة والإدارة والعمل الذكي.\">\n  <meta property=\"og:url\" content=\"https://ceo-notes.pages.dev/\">\n  <meta property=\"og:image\" content=\"\">\n  <meta property=\"article:published_time\" content=\"\">\n  <meta property=\"article:section\" content=\"\">\n  <meta name=\"twitter:card\" content=\"summary\">\n  <meta name=\"twitter:title\" content=\"CEO Notes | ملاحظات يومية في الإدارة والقيادة\">\n  <meta name=\"twitter:description\" content=\"أفكار عملية عن القيادة والإدارة والعمل الذكي.\">\n  <meta name=\"twitter:image\" content=\"\">\n  <style>\n    :root{color-scheme:dark;--bg:#090a0b;--panel:#121416;--panel2:#191b1d;--gold:#c8a568;--gold2:#e5cc98;--ink:#f7f3eb;--muted:#aaa59a;--line:#ffffff20;--max:1080px}\n    *{box-sizing:border-box}\n    html{scroll-behavior:smooth}\n    body{margin:0;background:radial-gradient(ellipse at 50% -20%,#6b51231c,transparent 48%),var(--bg);color:var(--ink);font-family:system-ui,-apple-system,\"Segoe UI\",Tahoma,Arial,sans-serif;line-height:1.85}\n    a{color:inherit;text-decoration:none}\n    button,input{font:inherit}\n    .wrap{width:min(var(--max),92%);margin-inline:auto}\n    .topbar{border-bottom:1px solid var(--line);background:#090a0bea}\n    .nav{min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:20px}\n    .brand{display:flex;align-items:center;gap:13px}\n    .mark{width:44px;height:44px;border:1px solid #c8a568a8;border-radius:13px;display:grid;place-items:center;color:var(--gold2);font-weight:800;letter-spacing:-2px;background:linear-gradient(145deg,#292219,#0d0e0f)}\n    .brand-name{display:grid;line-height:1.25}\n    .brand-name strong{font-size:16px;letter-spacing:2px}\n    .brand-name small{font-size:10px;color:var(--gold);letter-spacing:1.5px;margin-top:4px}\n    .navlinks{display:flex;gap:24px;color:#c9c4b9;font-size:13px}\n    .navlinks a:hover{color:var(--gold2)}\n    .hero{padding:76px 0 64px;text-align:center}\n    .eyebrow{display:inline-flex;align-items:center;gap:10px;color:var(--gold2);font-size:11px;letter-spacing:2px}\n    .eyebrow:before,.eyebrow:after{content:\"\";width:24px;height:1px;background:var(--gold)}\n    h1{font-size:clamp(36px,6vw,66px);line-height:1.2;margin:18px 0 14px;letter-spacing:-1.5px}\n    h1 span{color:var(--gold2)}\n    .hero p{max-width:690px;margin:0 auto;color:#bcb7ad;font-size:16px}\n    .hero-note{display:inline-flex;margin-top:27px;padding:7px 14px;border:1px solid #c8a56855;border-radius:30px;color:#d6c39d;font-size:11px}\n    .market-watch{padding:0 0 42px}\n    .market-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}\n    .market-card{background:linear-gradient(145deg,#17191b,#101214);border:1px solid var(--line);border-radius:13px;padding:14px;min-width:0}\n    .market-label{font-size:11px;color:#d8c7a5}\n    .market-value{font-size:clamp(17px,2.4vw,23px);font-weight:750;font-variant-numeric:tabular-nums;direction:ltr;text-align:right;white-space:nowrap}\n    .market-unit{font-size:10px;color:var(--muted);text-align:right}\n    .market-note{font-size:10px;color:#928d83;margin:12px 0 0}\n    .market-updated{font-size:10px;color:var(--muted);text-align:left}\n    .world-clock{padding:0 0 48px}\n    .clock-heading{display:flex;align-items:end;justify-content:space-between;gap:14px;margin-bottom:15px}\n    .clock-heading h2{font-size:19px;margin:0}\n    .clock-heading p{font-size:11px;color:var(--muted);margin:0}\n    .clocks{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:11px}\n    .clock{background:linear-gradient(145deg,#17191b,#101214);border:1px solid var(--line);border-radius:13px;padding:14px;min-width:0}\n    .clock-city{font-size:11px;color:#d8c7a5}\n    .clock-time{font-size:clamp(17px,2.5vw,25px);font-weight:700;letter-spacing:.5px;direction:ltr;text-align:right;font-variant-numeric:tabular-nums}\n    .clock-date{font-size:10px;color:var(--muted);direction:ltr;text-align:right}\n    .clock-zone{font-size:9px;color:#8d8980;margin-top:3px}\n    .toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 15px}\n    .section-title{margin:0;font-size:23px}\n    .count{color:var(--muted);font-size:12px}\n    .archive-tools{display:flex;align-items:center;gap:9px;width:min(520px,100%)}\n    .search{width:min(330px,100%);background:#101214;border:1px solid var(--line);border-radius:9px;padding:11px 14px;color:var(--ink);outline:none}\n    .archive-tools .search{width:auto;min-width:0;flex:1}\n    .search:focus{border-color:var(--gold)}\n    .category-select{min-width:155px;background:#101214;border:1px solid var(--line);border-radius:9px;padding:11px 13px;color:var(--ink);font:inherit;font-size:12px}\n    .category-select:focus-visible,.tag-filter:focus-visible,.topic-tag:focus-visible{outline:2px solid var(--gold);outline-offset:2px}\n    .tag-filters{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 22px}\n    .tag-filter{border:1px solid #ffffff24;background:#101214;color:#c9c4b9;border-radius:30px;padding:6px 11px;font:inherit;font-size:10px;cursor:pointer}\n    .tag-filter[aria-pressed=\"true\"]{border-color:#c8a568;background:#c8a56820;color:var(--gold2)}\n    .post-category{display:inline-flex;align-items:center;border:1px solid #c8a56855;border-radius:30px;padding:3px 9px;color:var(--gold2);font-size:10px;white-space:nowrap}\n    .topic-tags{display:flex;flex-wrap:wrap;gap:6px}\n    .topic-tag{display:inline-flex;border:1px solid #c8a56835;border-radius:30px;padding:3px 8px;color:#d6c39d;background:#c8a5680d;font-size:10px}\n    .posts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;padding-bottom:75px}\n    .post{background:linear-gradient(145deg,#17191b,#101214);border:1px solid var(--line);border-radius:17px;padding:23px;min-width:0}\n    .post-top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}\n    .day{color:var(--gold2);font-size:11px;letter-spacing:1.2px;font-weight:700}\n    .date{color:#88857e;font-size:10px}\n    .post h3{font-size:20px;line-height:1.5;margin:0 0 13px;color:#f2e8d4}\n    .post-link:hover{color:var(--gold2)}\n    .article{white-space:pre-line;color:#d0cbc1;font-size:13px;line-height:2;margin:0}\n    .post-actions{display:flex;justify-content:flex-start;margin-top:14px}\n    .share-button{border:1px solid #c8a56866;background:#c8a56812;color:var(--gold2);border-radius:8px;padding:7px 13px;font-size:11px;cursor:pointer}\n    .share-button:hover,.share-button:focus-visible{background:#c8a56824;border-color:var(--gold);outline:none}\n    .detail{border-top:1px solid var(--line);margin-top:18px;padding-top:15px;display:grid;gap:12px}\n    .detail-block{font-size:12px;color:#c8c2b7}\n    .detail-block strong{display:block;color:var(--gold2);font-size:11px;margin-bottom:3px}\n    .hashtags{display:flex;flex-wrap:wrap;gap:7px;margin-top:3px}\n    .tag{color:#d6c39d;font-size:10px;background:#c8a56812;border:1px solid #c8a56835;border-radius:30px;padding:3px 8px}\n    .empty{grid-column:1/-1;text-align:center;padding:48px 22px;border:1px dashed #ffffff35;border-radius:16px;color:var(--muted)}\n    .empty strong{display:block;color:var(--gold2);font-size:17px;margin-bottom:8px}\n    .about{border-top:1px solid var(--line);background:#0d0f10;padding:45px 0}\n    .about-inner{max-width:760px;margin:auto;text-align:center}\n    .about h2{font-size:22px;margin:0 0 8px}\n    .about p{color:var(--muted);font-size:13px;margin:0}\n    footer{padding:22px 0;color:#817d75;font-size:11px;border-top:1px solid var(--line)}\n    .footer-row{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}\n    @media(max-width:700px){.market-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.clocks{grid-template-columns:repeat(2,minmax(0,1fr))}.clock:last-child{grid-column:1/-1}.nav{min-height:68px}.navlinks{gap:13px;font-size:11px}.mark{width:39px;height:39px}.brand-name strong{font-size:13px}.hero{padding:56px 0 44px}.hero p{font-size:14px}.toolbar{align-items:stretch;flex-direction:column}.search{width:100%}.posts{grid-template-columns:1fr}.post{padding:19px}.post h3{font-size:18px}}\n    @media(max-width:700px){.archive-tools{width:100%;align-items:stretch;flex-direction:column}.archive-tools .search,.category-select{width:100%}.tag-filters{margin-bottom:18px}}\n    @media(max-width:420px){.navlinks a:last-child{display:none}.brand-name small{font-size:9px}}\n    @media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n  </style>\n  <link rel=\"stylesheet\" href=\"/radio.css\">\n</head>\n<body>\n  <header class=\"topbar\">\n    <div class=\"wrap nav\">\n      <a class=\"brand\" href=\"/\" aria-label=\"CEO Notes\">\n        <span class=\"mark\" aria-hidden=\"true\">CN</span>\n        <span class=\"brand-name\"><strong>CEO NOTES</strong><small>LEADERSHIP · BUSINESS · MINDSET</small></span>\n      </a>\n      <nav class=\"navlinks\" aria-label=\"التنقل\">\n        <a href=\"#latest\">المقالات</a>\n        <a href=\"#radio\">الراديو</a>\n        <a href=\"#about\">عن السلسلة</a>\n        <a href=\"https://www.facebook.com/115226621594988/\" target=\"_blank\" rel=\"noopener noreferrer\">صفحة فيسبوك</a>\n      </nav>\n    </div>\n  </header>\n\n  <main>\n    <section class=\"hero\">\n      <div class=\"wrap\">\n        <div class=\"eyebrow\">ملاحظات من أرض الواقع</div>\n        <h1>فكر أوضح.<br><span>وقُد بوعي أكبر.</span></h1>\n        <p>مساحة يومية لأفكار عملية عن القيادة والإدارة والعمل الذكي. مش شعارات محفوظة؛ ملاحظات تساعدك تشوف المشكلة من زاوية مختلفة وتحوّل الفكرة لخطوة قابلة للتنفيذ.</p>\n        <div class=\"hero-note\">مقال جديد كل يوم · فكرة · تحدٍ عملي · نقاش</div>\n      </div>\n    </section>\n\n    <section class=\"wrap market-watch\" aria-labelledby=\"market-title\">\n      <div class=\"clock-heading\">\n        <div>\n          <h2 id=\"market-title\">مؤشرات العملات والذهب</h2>\n          <p>أسعار مرجعية يومية من مصادر مفتوحة</p>\n        </div>\n        <div class=\"market-updated\" id=\"market-updated\" aria-live=\"polite\">جارٍ تحميل البيانات…</div>\n      </div>\n      <div class=\"market-grid\" id=\"market-board\" aria-live=\"polite\">\n        <div class=\"market-card\"><div class=\"market-label\">أسعار العملات</div><div class=\"market-value\">—</div><div class=\"market-unit\">جارٍ التحميل</div></div>\n      </div>\n      <p class=\"market-note\">الأسعار مرجعية يومية وليست أسعار تداول لحظية أو أسعار شراء وبيع البنوك. قيمة الذهب محسوبة من أونصة تروي XAU، ولا تمثل سعر المشغولات أو السعر المحلي بعد المصنعية والضرائب. المصدر: <a href=\"https://frankfurter.dev/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:var(--gold2)\">Frankfurter</a>.</p>\n    </section>\n\n    <section class=\"wrap world-clock\" aria-labelledby=\"clock-title\">\n      <div class=\"clock-heading\">\n        <div>\n          <h2 id=\"clock-title\">ساعات الأعمال حول العالم</h2>\n          <p>توقيت مباشر حسب المناطق الزمنية الرسمية، دون API أو اشتراك خارجي.</p>\n        </div>\n      </div>\n      <div class=\"clocks\" id=\"world-clocks\">\n        <div class=\"clock\"><div class=\"clock-city\">القاهرة</div><div class=\"clock-time\">--:--:--</div><div class=\"clock-zone\">Africa/Cairo</div></div>\n        <div class=\"clock\"><div class=\"clock-city\">لندن</div><div class=\"clock-time\">--:--:--</div><div class=\"clock-zone\">Europe/London</div></div>\n        <div class=\"clock\"><div class=\"clock-city\">نيويورك</div><div class=\"clock-time\">--:--:--</div><div class=\"clock-zone\">America/New_York</div></div>\n        <div class=\"clock\"><div class=\"clock-city\">موسكو</div><div class=\"clock-time\">--:--:--</div><div class=\"clock-zone\">Europe/Moscow</div></div>\n        <div class=\"clock\"><div class=\"clock-city\">دبي</div><div class=\"clock-time\">--:--:--</div><div class=\"clock-zone\">Asia/Dubai</div></div>\n      </div>\n    </section>\n\n    <section class=\"wrap radio-section\" id=\"radio\" aria-labelledby=\"radio-title\">\n      <div class=\"radio-panel\" id=\"ceo-radio\">\n        <div class=\"radio-head\">\n          <div><h2 id=\"radio-title\">راديو CEO Notes</h2><p>اكتشف محطات إذاعية مجانية من مصر والعالم، واستمع مباشرة من مصدر البث.</p></div>\n          <span class=\"radio-free\">مجاني · بدون تسجيل</span>\n        </div>\n        <form class=\"radio-controls\" id=\"radio-form\">\n          <input class=\"radio-input\" id=\"radio-search\" type=\"search\" maxlength=\"100\" placeholder=\"ابحث باسم محطة إذاعية…\" aria-label=\"ابحث عن محطة إذاعية\">\n          <select class=\"radio-country\" id=\"radio-country\" aria-label=\"اختر الدولة\"><option value=\"\">كل الدول</option><option value=\"Egypt\">مصر</option><option value=\"United Arab Emirates\">الإمارات</option><option value=\"Saudi Arabia\">السعودية</option><option value=\"United Kingdom\">بريطانيا</option><option value=\"The United States Of America\">الولايات المتحدة</option></select>\n          <button class=\"radio-search-btn\" type=\"submit\">ابحث عن محطات</button>\n        </form>\n        <div class=\"radio-presets\" aria-label=\"تصنيفات الراديو\">\n          <button class=\"radio-filter\" type=\"button\" data-radio-tag=\"\" aria-pressed=\"true\">الأكثر استماعًا</button>\n          <button class=\"radio-filter\" type=\"button\" data-radio-tag=\"arabic\" aria-pressed=\"false\">عربي</button>\n          <button class=\"radio-filter\" type=\"button\" data-radio-tag=\"news\" aria-pressed=\"false\">أخبار</button>\n          <button class=\"radio-filter\" type=\"button\" data-radio-tag=\"jazz\" aria-pressed=\"false\">جاز</button>\n          <button class=\"radio-filter\" type=\"button\" data-radio-tag=\"pop\" aria-pressed=\"false\">موسيقى</button>\n        </div>\n        <p class=\"radio-status\" id=\"radio-status\" role=\"status\" aria-live=\"polite\">اختر تصنيفًا أو ابحث عن محطة لبدء الاستماع.</p>\n        <div class=\"radio-results\" id=\"radio-results\"><div class=\"radio-empty\">المحطات ستظهر هنا بعد البحث.</div></div>\n        <div class=\"radio-player\">\n          <div class=\"radio-now\"><strong>يعمل الآن</strong><span id=\"radio-now-name\">لم يتم اختيار محطة</span><span id=\"radio-now-country\">اختر محطة من القائمة</span></div>\n          <audio id=\"radio-audio\" controls preload=\"none\" aria-label=\"مشغل الراديو\"></audio>\n        </div>\n        <p class=\"radio-disclaimer\">المحطات وروابط البث مقدمة من دليل Radio Browser المفتوح. الصوت يأتي مباشرة من خوادم المحطات؛ لا يستضيف CEO Notes البث ولا يسجله أو يعيد توزيعه. قد تتوقف بعض المحطات أو تقيّد الاستماع حسب الدولة. لأمان الموقع، نعرض روابط البث الآمنة HTTPS فقط. <a href=\"https://www.radio-browser.info/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:var(--gold2)\">المصدر والترخيص</a>.</p>\n      </div>\n    </section>\n\n    <section class=\"wrap\" id=\"latest\">\n      <div id=\"archive-controls\">\n        <div class=\"toolbar\">\n          <div>\n            <h2 class=\"section-title\">أحدث الملاحظات</h2>\n            <div class=\"count\" id=\"count\" aria-live=\"polite\">جارٍ تحميل المقالات…</div>\n          </div>\n          <div class=\"archive-tools\">\n            <input class=\"search\" id=\"search\" type=\"search\" placeholder=\"ابحث في العناوين والمقالات…\" aria-label=\"ابحث في المقالات\">\n            <select class=\"category-select\" id=\"category-filter\" aria-label=\"تصفية المقالات حسب القسم\">\n              <option value=\"\">كل الأقسام</option>\n            </select>\n          </div>\n        </div>\n        <div class=\"tag-filters\" id=\"tag-filters\" aria-label=\"تصفية المقالات حسب الموضوع\"></div>\n      </div>\n      <div class=\"posts\" id=\"posts\" aria-live=\"polite\">\n        <div class=\"empty\"><strong>لحظة واحدة…</strong>بنجهز أحدث الملاحظات للعرض.</div>\n      </div>\n    </section>\n\n    <section class=\"about\" id=\"about\">\n      <div class=\"wrap about-inner\">\n        <h2>عن CEO Notes</h2>\n        <p>سلسلة مستقلة تناقش مواقف العمل والقيادة من منظور عملي. كل مقال يقدّم فكرة واضحة، وتطبيقًا صغيرًا، وسؤالًا يفتح باب التفكير والنقاش.</p>\n        <p style=\"margin-top:18px\"><a href=\"https://www.facebook.com/115226621594988/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;padding:10px 18px;border:1px solid #c8a568;border-radius:30px;color:#e5cc98\">تابع CEO Notes على Facebook</a></p>\n      </div>\n    </section>\n  </main>\n\n  <footer>\n    <div class=\"wrap footer-row\">\n      <span>© <span id=\"year\"></span> CEO Notes</span>\n      <span>أفكار عملية. قرارات أوضح. أثر يدوم.</span>\n    </div>\n  </footer>\n\n  <script>\n    (function(){\n      \"use strict\";\n      const list = document.getElementById(\"posts\");\n      const search = document.getElementById(\"search\");\n      const categoryFilter = document.getElementById(\"category-filter\");\n      const tagFilters = document.getElementById(\"tag-filters\");\n      const archiveControls = document.getElementById(\"archive-controls\");\n      const count = document.getElementById(\"count\");\n      const marketBoard = document.getElementById(\"market-board\");\n      const marketUpdated = document.getElementById(\"market-updated\");\n      function marketCard(label,value,unit){\n        const card=node(\"div\",\"market-card\");\n        card.append(node(\"div\",\"market-label\",label));\n        card.append(node(\"div\",\"market-value\",value));\n        card.append(node(\"div\",\"market-unit\",unit));\n        return card;\n      }\n      async function loadMarkets(){\n        try{\n          const response=await fetch(\"/markets\",{cache:\"no-store\",headers:{\"Accept\":\"application/json\"}});\n          if(!response.ok) throw new Error(\"market_data_unavailable\");\n          const data=await response.json();\n          const fx=Object.fromEntries((Array.isArray(data.fx)?data.fx:[]).map(item=>[item.quote,Number(item.rate)]));\n          const gold=Object.fromEntries((Array.isArray(data.gold)?data.gold:[]).map(item=>[item.quote,Number(item.rate)]));\n          const fmt=(value,digits=4)=>Number(value).toLocaleString(\"en-US\",{maximumFractionDigits:digits});\n          const cards=[];\n          const pairs=[\n            [\"دولار / جنيه مصري\",\"EGP\",\"جنيه لكل دولار\",3],\n            [\"دولار / يورو\",\"EUR\",\"يورو لكل دولار\",4],\n            [\"دولار / إسترليني\",\"GBP\",\"إسترليني لكل دولار\",4],\n            [\"دولار / روبل\",\"RUB\",\"روبل لكل دولار\",2],\n            [\"دولار / درهم إماراتي\",\"AED\",\"درهم لكل دولار\",4],\n            [\"دولار / ريال سعودي\",\"SAR\",\"ريال لكل دولار\",4]\n          ];\n          pairs.forEach(([label,code,unit,digits])=>{\n            if(Number.isFinite(fx[code])) cards.push(marketCard(label,fmt(fx[code],digits),unit));\n          });\n          if(Number.isFinite(gold.USD)) cards.push(marketCard(\"أونصة الذهب\",\"$\"+fmt(gold.USD,2),\"دولار أمريكي / أونصة تروي\"));\n          if(Number.isFinite(gold.EGP)){\n            cards.push(marketCard(\"أونصة الذهب\",\"ج.م \"+fmt(gold.EGP,0),\"جنيه مصري / أونصة تروي\"));\n            cards.push(marketCard(\"جرام ذهب 24 قيراط\",\"ج.م \"+fmt(gold.EGP/31.1034768,2),\"قيمة مرجعية محسوبة قبل المصنعية والضرائب\"));\n          }\n          if(!cards.length) throw new Error(\"empty_market_data\");\n          marketBoard.replaceChildren(...cards);\n          marketUpdated.textContent=\"تاريخ البيانات: \"+String(data.date || \"غير متاح\");\n        }catch(error){\n          marketBoard.replaceChildren();\n          marketBoard.append(node(\"div\",\"empty\",\"تعذر تحميل المؤشرات حاليًا. حاول مرة أخرى لاحقًا.\"));\n          marketUpdated.textContent=\"البيانات غير متاحة مؤقتًا\";\n        }\n      }\n      loadMarkets();\n      const clockRoot = document.getElementById(\"world-clocks\");\n      document.getElementById(\"year\").textContent = String(new Date().getFullYear());\n      const clockFormatters = [\n        {zone:\"Africa/Cairo\",time:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Africa/Cairo\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false}),date:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Africa/Cairo\",weekday:\"short\",day:\"2-digit\",month:\"short\"})},\n        {zone:\"Europe/London\",time:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Europe/London\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false}),date:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Europe/London\",weekday:\"short\",day:\"2-digit\",month:\"short\"})},\n        {zone:\"America/New_York\",time:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"America/New_York\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false}),date:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"America/New_York\",weekday:\"short\",day:\"2-digit\",month:\"short\"})},\n        {zone:\"Europe/Moscow\",time:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Europe/Moscow\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false}),date:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Europe/Moscow\",weekday:\"short\",day:\"2-digit\",month:\"short\"})},\n        {zone:\"Asia/Dubai\",time:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Asia/Dubai\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false}),date:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Asia/Dubai\",weekday:\"short\",day:\"2-digit\",month:\"short\"})}\n      ];\n      function updateWorldClocks(){\n        const now = new Date();\n        clockRoot.querySelectorAll(\".clock\").forEach((card,index)=>{\n          const item = clockFormatters[index];\n          if(!item) return;\n          card.querySelector(\".clock-time\").textContent = item.time.format(now);\n          card.querySelector(\".clock-date\").textContent = item.date.format(now);\n        });\n      }\n      clockRoot.querySelectorAll(\".clock\").forEach((card,index)=>{\n        const date = document.createElement(\"div\");\n        date.className = \"clock-date\";\n        card.append(date);\n        const zone = document.createElement(\"div\");\n        zone.className = \"clock-zone\";\n        zone.textContent = clockFormatters[index].zone;\n        card.querySelector(\".clock-zone\").replaceWith(zone);\n      });\n      updateWorldClocks();\n      window.setInterval(updateWorldClocks,1000);\n      let posts = [];\n      let activeTag = \"\";\n      const selectedPostMatch = location.pathname.match(/^\\/post\\/(\\d+)\\/?$/);\n      const selectedPostDay = selectedPostMatch ? Number(selectedPostMatch[1]) : null;\n      if(selectedPostDay) archiveControls.hidden = true;\n\n      function node(tag, className, value){\n        const el = document.createElement(tag);\n        if(className) el.className = className;\n        if(value !== undefined && value !== null) el.textContent = String(value);\n        return el;\n      }\n      function makePost(post){\n        const card = node(\"article\",\"post\");\n        if(post.day !== undefined) card.id = \"post-\" + String(post.day);\n        const top = node(\"div\",\"post-top\");\n        top.append(node(\"span\",\"day\",\"CEO NOTES · DAY \" + post.day));\n        if(post.category) top.append(node(\"span\",\"post-category\",post.category));\n        if(post.publishedAt) top.append(node(\"time\",\"date\",post.publishedAt));\n        card.append(top);\n        if(post.imageUrl){\n          const image = document.createElement(\"img\");\n          image.src = post.imageUrl;\n          image.alt = \"صورة توضيحية: \" + (post.title || \"CEO Notes\");\n          image.loading = \"lazy\";\n          image.decoding = \"async\";\n          image.style.cssText = \"display:block;width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:12px;margin:4px 0 16px;border:1px solid #c8a56855\";\n          card.append(image);\n        }\n        const heading = node(\"h3\",\"\");\n        const titleLink = node(\"a\",\"post-link\",post.title || \"ملاحظة يومية\");\n        titleLink.href = \"/post/\" + encodeURIComponent(String(post.day || \"\"));\n        heading.append(titleLink);\n        card.append(heading);\n        card.append(node(\"p\",\"article\",post.article || \"\"));\n        const detail = node(\"div\",\"detail\");\n        if(post.ideaOfTheDay){\n          const block = node(\"div\",\"detail-block\");\n          block.append(node(\"strong\",\"\",\"فكرة اليوم\"));\n          block.append(node(\"span\",\"\",post.ideaOfTheDay));\n          detail.append(block);\n        }\n        if(post.ceoChallenge){\n          const block = node(\"div\",\"detail-block\");\n          block.append(node(\"strong\",\"\",\"CEO CHALLENGE\"));\n          block.append(node(\"span\",\"\",post.ceoChallenge));\n          detail.append(block);\n        }\n        if(post.discussionQuestion){\n          const block = node(\"div\",\"detail-block\");\n          block.append(node(\"strong\",\"\",\"للنقاش\"));\n          block.append(node(\"span\",\"\",post.discussionQuestion));\n          detail.append(block);\n        }\n        const topicTags = Array.isArray(post.tags) ? post.tags : [];\n        if(topicTags.length){\n          const topicList = node(\"div\",\"topic-tags\");\n          topicTags.forEach(tag => topicList.append(node(\"span\",\"topic-tag\",tag)));\n          detail.append(topicList);\n        }\n        const tags = Array.isArray(post.hashtags) ? post.hashtags : String(post.hashtags || \"\").split(/\\s+/).filter(Boolean);\n        if(tags.length){\n          const tagList = node(\"div\",\"hashtags\");\n          tags.filter(Boolean).forEach(tag => tagList.append(node(\"span\",\"tag\",tag)));\n          detail.append(tagList);\n        }\n        card.append(detail);\n        const actions = node(\"div\",\"post-actions\");\n        const share = node(\"button\",\"share-button\",\"مشاركة المقال\");\n        share.type = \"button\";\n        share.addEventListener(\"click\",async()=>{\n          const shareUrl = location.origin + \"/post/\" + encodeURIComponent(String(post.day || \"\"));\n          const payload = {title:post.title || \"CEO Notes\",text:(post.title || \"CEO Notes\") + \" — CEO Notes\",url:shareUrl};\n          try{\n            if(navigator.share){await navigator.share(payload);}\n            else if(navigator.clipboard && navigator.clipboard.writeText){\n              await navigator.clipboard.writeText(shareUrl);\n              share.textContent = \"تم نسخ الرابط\";\n              share.setAttribute(\"aria-label\",\"تم نسخ رابط المقال\");\n            }else{\n              window.open(\"https://www.facebook.com/sharer/sharer.php?u=\" + encodeURIComponent(shareUrl),\"_blank\",\"noopener,noreferrer\");\n            }\n          }catch(error){\n            if(error && error.name !== \"AbortError\"){\n              share.textContent = \"تعذرت المشاركة\";\n            }\n          }\n        });\n        actions.append(share);\n        card.append(actions);\n        return card;\n      }\n      function renderFilters(){\n        const currentCategory = categoryFilter.value;\n        const categories = [...new Set(posts.map(post => post.category).filter(Boolean))]\n          .sort((a,b) => a.localeCompare(b,\"ar\"));\n        categoryFilter.replaceChildren(node(\"option\",\"\",\"كل الأقسام\"));\n        categories.forEach(category => {\n          const option = node(\"option\",\"\",category);\n          option.value = category;\n          categoryFilter.append(option);\n        });\n        categoryFilter.value = categories.includes(currentCategory) ? currentCategory : \"\";\n\n        const tags = [...new Set(posts.flatMap(post => Array.isArray(post.tags) ? post.tags : []))]\n          .filter(Boolean)\n          .sort((a,b) => a.localeCompare(b,\"ar\"));\n        tagFilters.replaceChildren();\n        const all = node(\"button\",\"tag-filter\",\"كل الوسوم\");\n        all.type = \"button\";\n        all.setAttribute(\"aria-pressed\",String(!activeTag));\n        all.addEventListener(\"click\",() => { activeTag = \"\"; renderFilters(); render(); });\n        tagFilters.append(all);\n        tags.forEach(tag => {\n          const button = node(\"button\",\"tag-filter\",tag);\n          button.type = \"button\";\n          button.setAttribute(\"aria-pressed\",String(activeTag === tag));\n          button.addEventListener(\"click\",() => { activeTag = tag; renderFilters(); render(); });\n          tagFilters.append(button);\n        });\n      }\n      function render(){\n        const q = search.value.trim().toLocaleLowerCase(\"ar\");\n        const selectedCategory = categoryFilter.value;\n        const filtered = posts.filter(post => {\n          if(selectedPostDay && Number(post.day) !== selectedPostDay) return false;\n          if(selectedCategory && post.category !== selectedCategory) return false;\n          const tags = Array.isArray(post.tags) ? post.tags : [];\n          if(activeTag && !tags.includes(activeTag)) return false;\n          const haystack = [post.day,post.title,post.article,post.ideaOfTheDay,post.ceoChallenge,post.discussionQuestion,post.category,post.tags,post.hashtags].join(\" \").toLocaleLowerCase(\"ar\");\n          return haystack.includes(q);\n        });\n        count.textContent = filtered.length + \" مقال منشور\";\n        list.replaceChildren();\n        if(!filtered.length){\n          const empty = node(\"div\",\"empty\");\n          empty.append(node(\"strong\",\"\",posts.length ? \"مفيش نتائج مطابقة\" : \"أول ملاحظة في الطريق\"));\n          empty.append(node(\"span\",\"\",posts.length ? \"جرّب كلمة بحث مختلفة.\" : \"المقالات ستظهر هنا تلقائيًا بعد اعتماد ونشر أول منشور.\"));\n          list.append(empty);\n          return;\n        }\n        filtered.forEach(post => list.append(makePost(post)));\n      }\n      search.addEventListener(\"input\",render);\n      categoryFilter.addEventListener(\"change\",render);\n      async function loadPosts(){\n        const fallbackUrl = (location.pathname.endsWith(\"/\") ? location.pathname : location.pathname + \"/\") + \"posts.json\";\n        let firstError = null;\n        for(const url of [\"/feed\",fallbackUrl]){\n          try{\n            const response = await fetch(url,{cache:\"no-store\",headers:{\"Accept\":\"application/json\"}});\n            if(!response.ok) throw new Error(\"HTTP \" + response.status);\n            const data = await response.json();\n            const items = Array.isArray(data) ? data : (Array.isArray(data.posts) ? data.posts : []);\n            if(!Array.isArray(items)) throw new Error(\"invalid_posts_format\");\n            posts = items.filter(item => item && item.status !== \"Draft\" && item.status !== \"Reserved\")\n              .sort((a,b) => Number(b.day || 0) - Number(a.day || 0));\n            renderFilters();\n            if(selectedPostDay){\n              const selected = posts.find(post => Number(post.day) === selectedPostDay);\n              if(selected){\n                document.title = (selected.title || \"CEO Notes\") + \" | CEO Notes\";\n                const description = String(selected.article || \"\").slice(0,155);\n                const descriptionMeta = document.querySelector('meta[name=\"description\"]');\n                if(descriptionMeta) descriptionMeta.content = description;\n                const canonical = document.querySelector('link[rel=\"canonical\"]');\n                if(canonical) canonical.href = location.origin + \"/post/\" + selectedPostDay;\n                const ogTitle = document.querySelector('meta[property=\"og:title\"]');\n                if(ogTitle) ogTitle.content = document.title;\n                const ogDescription = document.querySelector('meta[property=\"og:description\"]');\n                if(ogDescription) ogDescription.content = description;\n                const ogUrl = document.querySelector('meta[property=\"og:url\"]');\n                if(ogUrl) ogUrl.content = canonical ? canonical.href : location.href;\n                const imageUrl = typeof selected.imageUrl === \"string\" && selected.imageUrl.startsWith(\"https://\") ? selected.imageUrl : \"\";\n                const ogImage = document.querySelector('meta[property=\"og:image\"]');\n                if(ogImage) ogImage.content = imageUrl;\n                const twitterTitle = document.querySelector('meta[name=\"twitter:title\"]');\n                if(twitterTitle) twitterTitle.content = document.title;\n                const twitterDescription = document.querySelector('meta[name=\"twitter:description\"]');\n                if(twitterDescription) twitterDescription.content = description;\n                const twitterImage = document.querySelector('meta[name=\"twitter:image\"]');\n                if(twitterImage) twitterImage.content = imageUrl;\n                const twitterCard = document.querySelector('meta[name=\"twitter:card\"]');\n                if(twitterCard) twitterCard.content = imageUrl ? \"summary_large_image\" : \"summary\";\n              }\n            }\n            render();\n            return;\n          }catch(error){\n            if(!firstError) firstError = error;\n          }\n        }\n        list.replaceChildren();\n        const empty = node(\"div\",\"empty\");\n        empty.append(node(\"strong\",\"\",\"تعذر تحميل المقالات حاليًا\"));\n        empty.append(node(\"span\",\"\",\"حاول تحديث الصفحة بعد قليل.\"));\n        list.append(empty);\n        count.textContent = \"المحتوى غير متاح مؤقتًا\";\n      }\n      loadPosts();\n    })();\n  </script>\n<!-- CEO Notes live feed: Cloudflare Workers AI + KV -->\n  <script src=\"/radio.js\" defer></script>\n</body>\n</html>";
const RADIO_CSS=".radio-section{padding:0 0 68px}.radio-panel{border:1px solid #c8a56845;border-radius:18px;background:linear-gradient(145deg,#17191b,#0d1012);padding:24px}.radio-head{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:18px}.radio-head h2{margin:0 0 5px;font-size:23px;color:#f2e8d4}.radio-head p{margin:0;color:#aaa59a;font-size:12px}.radio-free{border:1px solid #c8a56866;border-radius:30px;padding:5px 11px;color:#e5cc98;font-size:10px;white-space:nowrap}.radio-controls{display:grid;grid-template-columns:minmax(0,1fr) 170px auto;gap:9px;margin-bottom:12px}.radio-input,.radio-country{min-width:0;border:1px solid #ffffff24;border-radius:9px;background:#090b0d;color:#f7f3eb;padding:11px 13px;font:inherit;font-size:12px}.radio-input:focus,.radio-country:focus{outline:2px solid #c8a568;outline-offset:1px}.radio-search-btn,.radio-filter{border:1px solid #c8a56870;background:#c8a56814;color:#e5cc98;border-radius:9px;padding:9px 13px;font:inherit;font-size:11px;cursor:pointer}.radio-search-btn:hover,.radio-filter:hover,.radio-filter[aria-pressed=true]{background:#c8a56830;border-color:#d7b878}.radio-presets{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 14px}.radio-status{min-height:24px;color:#b9b2a4;font-size:11px;margin:0 0 10px}.radio-results{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.radio-station{display:flex;flex-direction:column;gap:8px;min-width:0;padding:14px;border:1px solid #ffffff1c;border-radius:12px;background:#0d1012}.radio-station strong{font-size:13px;color:#f0e6d2;line-height:1.5;overflow-wrap:anywhere}.radio-meta{font-size:10px;color:#a9a398;line-height:1.7}.radio-station-actions{display:flex;align-items:center;gap:8px;margin-top:auto}.radio-play{border:0;border-radius:8px;background:#c8a568;color:#14110b;padding:7px 12px;font:inherit;font-weight:700;font-size:11px;cursor:pointer}.radio-home{color:#d9c69f;font-size:10px;text-decoration:underline;text-underline-offset:3px}.radio-player{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:12px;margin-top:17px;padding:13px;border:1px solid #c8a56850;border-radius:12px;background:#090b0d}.radio-now{min-width:0}.radio-now strong{display:block;color:#e5cc98;font-size:11px}.radio-now span{display:block;color:#c9c3b8;font-size:12px;overflow-wrap:anywhere}.radio-player audio{width:min(390px,100%);height:38px}.radio-disclaimer{margin:12px 0 0;color:#8f8b83;font-size:10px;line-height:1.8}.radio-empty{grid-column:1/-1;padding:22px;text-align:center;border:1px dashed #ffffff2c;border-radius:12px;color:#aaa59a;font-size:12px}@media(max-width:760px){.radio-results{grid-template-columns:repeat(2,minmax(0,1fr))}.radio-controls{grid-template-columns:1fr 140px}.radio-search-btn{grid-column:1/-1}}@media(max-width:480px){.radio-panel{padding:16px}.radio-head{flex-direction:column}.radio-results{grid-template-columns:1fr}.radio-controls{grid-template-columns:1fr}.radio-search-btn{grid-column:auto}.radio-player{grid-template-columns:1fr}.radio-player audio{width:100%}}";
const RADIO_JS="(() => {\n  \"use strict\";\n\n  const root = document.getElementById(\"ceo-radio\");\n  if (!root) return;\n\n  const hosts = [\n    \"https://de1.api.radio-browser.info\",\n    \"https://nl1.api.radio-browser.info\",\n    \"https://de2.api.radio-browser.info\"\n  ];\n\n  const form = root.querySelector(\"#radio-form\");\n  const search = root.querySelector(\"#radio-search\");\n  const country = root.querySelector(\"#radio-country\");\n  const results = root.querySelector(\"#radio-results\");\n  const status = root.querySelector(\"#radio-status\");\n  const audio = root.querySelector(\"#radio-audio\");\n  const nowName = root.querySelector(\"#radio-now-name\");\n  const nowCountry = root.querySelector(\"#radio-now-country\");\n  const presets = [...root.querySelectorAll(\"[data-radio-tag]\")];\n\n  let activeTag = \"\";\n  let requestId = 0;\n\n  function element(tag, className, value) {\n    const item = document.createElement(tag);\n    if (className) item.className = className;\n    if (value !== undefined && value !== null) item.textContent = String(value);\n    return item;\n  }\n\n  function announce(message) {\n    status.textContent = message;\n  }\n\n  function buildQuery() {\n    const params = new URLSearchParams({\n      hidebroken: \"true\",\n      limit: \"24\",\n      order: \"clickcount\",\n      reverse: \"true\",\n      is_https: \"true\",\n      hls: \"0\"\n    });\n\n    if (search.value.trim()) params.set(\"name\", search.value.trim().slice(0, 100));\n    if (country.value) params.set(\"country\", country.value);\n    if (activeTag) params.set(\"tag\", activeTag);\n\n    return params.toString();\n  }\n\n  function isPlayableStation(station) {\n    return station &&\n      typeof station.url_resolved === \"string\" &&\n      station.url_resolved.startsWith(\"https://\") &&\n      Number(station.hls) !== 1;\n  }\n\n  async function loadStations() {\n    const currentRequest = ++requestId;\n    results.replaceChildren(element(\"div\", \"radio-empty\", \"بنبحث عن محطات مناسبة…\"));\n    root.setAttribute(\"aria-busy\", \"true\");\n    announce(\"جارٍ الاتصال بدليل المحطات المفتوح.\");\n\n    const path = \"/json/stations/search?\" + buildQuery();\n\n    for (const host of hosts) {\n      const controller = new AbortController();\n      const timeout = window.setTimeout(() => controller.abort(), 9000);\n\n      try {\n        const response = await fetch(host + path, {\n          headers: { Accept: \"application/json\" },\n          signal: controller.signal,\n          cache: \"no-store\"\n        });\n\n        if (!response.ok) throw new Error(\"Radio directory HTTP \" + response.status);\n\n        const data = await response.json();\n        if (currentRequest !== requestId) return;\n\n        const stations = (Array.isArray(data) ? data : []).filter(isPlayableStation);\n        renderStations(stations);\n        return;\n      } catch (error) {\n        // Try the next public Radio Browser API host.\n      } finally {\n        window.clearTimeout(timeout);\n      }\n    }\n\n    if (currentRequest !== requestId) return;\n\n    results.replaceChildren(element(\"div\", \"radio-empty\", \"تعذر الوصول إلى دليل الراديو حاليًا. جرّب مرة أخرى لاحقًا.\"));\n    announce(\"الاتصال غير متاح الآن. لم يتم تشغيل أي بث تلقائيًا.\");\n    root.setAttribute(\"aria-busy\", \"false\");\n  }\n\n  function renderStations(stations) {\n    results.replaceChildren();\n\n    if (!stations.length) {\n      results.append(element(\"div\", \"radio-empty\", \"لا توجد محطات صوتية آمنة ومتوافقة بهذا الاختيار. جرّب تصنيفًا آخر.\"));\n      announce(\"لم نعثر على محطات HTTPS متوافقة مع مشغل المتصفح بهذا الاختيار.\");\n      root.setAttribute(\"aria-busy\", \"false\");\n      return;\n    }\n\n    stations.forEach((station) => {\n      const card = element(\"article\", \"radio-station\");\n      const name = element(\"strong\", \"\", station.name || \"محطة إذاعية\");\n      const metadata = element(\n        \"div\",\n        \"radio-meta\",\n        [station.country, station.language, station.codec, station.bitrate ? station.bitrate + \" kbps\" : \"\"]\n          .filter(Boolean)\n          .join(\" · \")\n      );\n\n      card.append(name, metadata);\n\n      const actions = element(\"div\", \"radio-station-actions\");\n      const play = element(\"button\", \"radio-play\", \"استمع\");\n      play.type = \"button\";\n\n      play.addEventListener(\"click\", async () => {\n        audio.pause();\n        audio.src = station.url_resolved;\n        audio.load();\n        nowName.textContent = station.name || \"محطة إذاعية\";\n        nowCountry.textContent = station.country || \"بث مباشر\";\n        announce(\"جارٍ تشغيل المحطة…\");\n\n        try {\n          await audio.play();\n          announce(\"يعمل البث الآن.\");\n        } catch (error) {\n          announce(\"لم يبدأ البث. قد تكون المحطة متوقفة أو غير متاحة في منطقتك.\");\n        }\n      });\n\n      actions.append(play);\n\n      if (typeof station.homepage === \"string\" && station.homepage.startsWith(\"https://\")) {\n        const homepage = element(\"a\", \"radio-home\", \"موقع المحطة\");\n        homepage.href = station.homepage;\n        homepage.target = \"_blank\";\n        homepage.rel = \"noopener noreferrer\";\n        actions.append(homepage);\n      }\n\n      card.append(actions);\n      results.append(card);\n    });\n\n    announce(\"تم العثور على \" + stations.length + \" محطة صوتية متوافقة ببث HTTPS. اختر استمع لبدء التشغيل.\");\n    root.setAttribute(\"aria-busy\", \"false\");\n  }\n\n  form.addEventListener(\"submit\", (event) => {\n    event.preventDefault();\n    loadStations();\n  });\n\n  presets.forEach((button) => {\n    button.addEventListener(\"click\", () => {\n      activeTag = button.dataset.radioTag || \"\";\n      presets.forEach((item) => item.setAttribute(\"aria-pressed\", String(item === button)));\n      loadStations();\n    });\n  });\n\n  audio.addEventListener(\"error\", () => announce(\"تعذر تشغيل هذا البث. جرّب محطة أخرى؛ روابط البث قد تتغير أو تتوقف.\"));\n  audio.addEventListener(\"playing\", () => announce(\"البث يعمل الآن.\"));\n  audio.addEventListener(\"pause\", () => {\n    if (audio.src) announce(\"تم إيقاف البث مؤقتًا.\");\n  });\n})();\n";
const POSTS="{\n  \"version\": 1,\n  \"posts\": [\n    {\n      \"day\": 25,\n      \"title\": \"لما الرقم يتحسن… والشغل يسوء\",\n      \"article\": \"مش كل رقم بيطلع لفوق معناه إن الشغل بيتحسن. ممكن المبيعات تزيد والعميل يرجع يشتكي، وممكن عدد المكالمات يكبر من غير ما مشكلة واحدة تتحل. الخطر إننا ننبهر بالمؤشر وننسى النتيجة اللي اتعمل المؤشر علشان يقيسها. الإدارة مش إنك تطارد رقم حلو في التقرير؛ الإدارة إنك تفهم الرقم بيقول إيه، وإيه اللي مستخبي وراه. اسأل دايمًا: هل التحسن ده حسّ به العميل والفريق فعلًا؟\",\n      \"ideaOfTheDay\": \"الرقم وسيلة للفهم، مش شهادة نجاح لوحده.\",\n      \"ceoChallenge\": \"اختار مؤشر بتتابعه، وحط جنبه مؤشر جودة يكشف أثره الحقيقي.\",\n      \"discussionQuestion\": \"إيه المؤشر اللي ممكن يبان ممتاز بينما التجربة على الأرض مش ممتازة؟\",\n      \"hashtags\": \"#CEO_Notes #CEO_Challenge #فكرة_اليوم #إدارة #قيادة\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-11-06\",\n      \"category\": \"الإدارة والأداء\",\n      \"tags\": [\n        \"مؤشرات الأداء\",\n        \"تجربة العميل\",\n        \"جودة الخدمة\"\n      ]\n    },\n    {\n      \"day\": 26,\n      \"title\": \"لما التفويض مش ضعف.. ده استثمار\",\n      \"article\": \"كتير من المديرين بيشوفوا التفويض كأنه خروج من المسؤولية، أو دليل إنهم مش قادرين يمسكوا كل التفاصيل. لكن التفويض الذكي مش إنك ترمي المهمة على حد وتمشي؛ هو إنك تبني شخص يقدر يشيل مسؤولية، وتديله فرصة يتعلم ويكبر.\\n\\nلما المدير يصر يعمل كل حاجة بنفسه، وقته بيتسحب في تفاصيل يومية، ومبيلاقيش مساحة يركز على القرارات اللي بتحرك الشغل لقدام. وفي نفس الوقت، الفريق بيتعود يستنى التعليمات بدل ما يفكر ويقترح. المشكلة مش بالضرورة في قدرات الناس؛ ساعات المشكلة في مساحة الثقة والصلاحية اللي بنديهالهم.\\n\\nالتفويض الصح يبدأ باختيار الشخص المناسب، وتوضيح النتيجة المطلوبة وحدود الصلاحية، وتوفير المعلومات والأدوات. بعد كده دورك يبقى متابعة وتوجيه، مش تدخل في كل خطوة. ولو حصل خطأ، ناقشه باعتباره فرصة تعلم، مش سبب تسحب المهمة فورًا.\\n\\nالقائد اللي بيعمل كل حاجة بنفسه ممكن يبان مشغول طول الوقت، لكنه بيصنع نقطة اختناق حوالين نفسه. أما اللي بيفوض بوعي، فهو بيضاعف قدرة الفريق وبيجهز ناس تقدر تتحمل مسؤولية أكبر.\",\n      \"ideaOfTheDay\": \"التفويض تمكين.. مش تخليص.\",\n      \"ceoChallenge\": \"خلال الـ48 ساعة الجاية، اختار مهمة روتينية بتعملها بنفسك، وفوضها لشخص في فريقك. وضّح النتيجة والصلاحيات، وقدّم الدعم من غير ما تسحب منه المسؤولية.\",\n      \"discussionQuestion\": \"إيه أكتر حاجة بتصعّب عليك تفويض المهام: الخوف من الخطأ، ضعف الثقة، ولا عدم وضوح الصلاحيات؟\",\n      \"hashtags\": \"#CEO_Notes #CEO_Challenge #فكرة_اليوم #إدارة #قيادة #تمكين_الفريق\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-11-07T18:47:11.607Z\",\n      \"imageUrl\": \"https://ceo-notes-ai.yasser-abdelaziz83.workers.dev/image/26\",\n      \"category\": \"القيادة\",\n      \"tags\": [\n        \"التفويض\",\n        \"تمكين الفريق\",\n        \"بناء الثقة\"\n      ]\n    },\n    {\n      \"day\": 27,\n      \"title\": \"لما الصمت بيسبق القرار.. ده مش تردد، ده تقدير\",\n      \"article\": \"كتير مننا بيفتكر إن سرعة اتخاذ القرار دليل على الكفاءة. بس الحقيقة، في مواقف كتير، الصمت والتفكير العميق قبل ما تقول أو تعمل أي حاجة بيكون علامة على تقدير للموقف. مش كل مشكلة ليها حل فوري، ومش كل رد فعل لازم يكون سريع. التأني بيخليك تشوف الصورة كاملة، وتفهم تبعيات قرارك. \\n\\nالفرق بين التردد والتفكير المنظم، إن التردد بيخليك متشتت، لكن التفكير المنظم بيخليك مركز. لو حسيت إنك محتاج وقت، خده. الموضوع مش في إنك تكون أسرع، الموضوع في إنك تكون أدق. \\n\\nالتواصل هنا مهم جداً. مش لازم تخبي إنك بتفكر، لكن أوضح إنك بتحاول تاخد القرار الصح. قول: \\\"محتاج شوية وقت عشان أجمع المعلومات\\\" أو \\\"عايز أفكر في الموضوع ده بعمق\\\". ده بيزرع الثقة، مش القلق. \\n\\nفي النهاية، القيادة مش بس في إصدار الأوامر، القيادة في إنك تعرف امتى تسكت وتفكر، وإمتى تتكلم وتتصرف. القرار المتأني، حتى لو اتأخر شوية، بيكون أقوى وأكثر فعالية.\",\n      \"ideaOfTheDay\": \"التفكير العميق قبل الفعل.. قوة مش ضعف.\",\n      \"ceoChallenge\": \"خلال الـ 48 ساعة الجاية، اختار قرار مهم كنت هتاخده بشكل سريع. أخد وقتك فيه، حلله بعمق، وقيّم النتائج المتوقعة. سجل ملاحظاتك.\",\n      \"discussionQuestion\": \"إزاي نقدر نزرع ثقافة التفكير المنظم والتأني في بيئة عمل سريعة الوتيرة؟\",\n      \"hashtags\": \"#CEO_Notes #CEO_Challenge #فكرة_اليوم #إدارة #قيادة #اتخاذ_القرار #تفكير_نقدي\",\n      \"publishedAt\": \"2026-11-07T21:42:03.981Z\",\n      \"status\": \"Published\",\n      \"imageUrl\": \"https://ceo-notes-ai.yasser-abdelaziz83.workers.dev/image/27\",\n      \"category\": \"القيادة\",\n      \"tags\": [\n        \"اتخاذ القرار\",\n        \"التفكير النقدي\",\n        \"التأني\"\n      ]\n    }\n  ]\n}\n";
const UPSTREAM="https://ceo-notes-ai.yasser-abdelaziz83.workers.dev/feed";
const CACHE_TTL=86400;
function cacheKey(origin,path){return new Request(new URL(path,origin),{method:"GET"});}
function normalizeEditorialFeed(feed){
 const fallback=JSON.parse(POSTS);
 const localPosts=Array.isArray(fallback?.posts)?fallback.posts:[];
 const byDay=new Map(localPosts.map(post=>[Number(post.day),post]));
 const sourcePosts=Array.isArray(feed?.posts)?feed.posts:[];
 const posts=sourcePosts.map(post=>{
  const local=byDay.get(Number(post?.day))||{};
  const suppliedTags=Array.isArray(post?.tags)&&post.tags.length?post.tags:[];
  const localTags=Array.isArray(local.tags)&&local.tags.length?local.tags:[];
  const hashtagText=Array.isArray(post?.hashtags)?post.hashtags.join(" "):String(post?.hashtags||"");
  const derivedTags=hashtagText.split(/\s+/).map(tag=>tag.replace(/^#/,"").replace(/_/g," ")).filter(tag=>tag&&!["CEO Notes","CEO Challenge","فكرة اليوم"].includes(tag));
  const tags=suppliedTags.length?suppliedTags:(localTags.length?localTags:[...new Set(derivedTags)]);
  return {...post,category:post.category||local.category||"غير مصنّف",tags};
 });
 return {...feed,posts};
}
async function latestFeed(origin){
 const key=cacheKey(origin,"/__ceo_notes_feed_cache");
 try{
  const upstream=await fetch(UPSTREAM,{headers:{"Accept":"application/json"},cf:{cacheTtl:0}});
  if(!upstream.ok)throw new Error("feed_unavailable");
  const parsed=JSON.parse(await upstream.text());
  const normalized=normalizeEditorialFeed(parsed);
  const body=JSON.stringify(normalized);
  try{await caches.default.put(key,new Response(body,{headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"public, max-age="+CACHE_TTL,"X-Content-Type-Options":"nosniff"}}));}catch(e){}
  return normalized;
 }catch(e){
  try{const cached=await caches.default.match(key);if(cached)return normalizeEditorialFeed(JSON.parse(await cached.text()));}catch(cacheError){}
  return normalizeEditorialFeed(JSON.parse(POSTS));
 }
}
async function marketData(origin){
 const key=cacheKey(origin,"/__ceo_notes_markets_cache");
 let staleData=null;
 try{
  const cached=await caches.default.match(key);
  if(cached){
   const candidate=JSON.parse(await cached.text());
   const fetchedAt=Date.parse(candidate.fetchedAt||""),age=Date.now()-fetchedAt;
   if(Number.isFinite(age)&&age>=0&&age<=21600000)return {...candidate,stale:false};
   if(Number.isFinite(age)&&age>21600000&&age<=259200000)staleData=candidate;
  }
 }catch(e){}
 try{
  const urls=[
   "https://api.frankfurter.dev/v2/rates?base=USD&quotes=EGP,EUR,GBP,RUB,AED,SAR",
   "https://api.frankfurter.dev/v2/rates?base=XAU&quotes=USD,EGP"
  ];
  const responses=await Promise.all(urls.map(url=>fetch(url,{headers:{"Accept":"application/json"},cf:{cacheTtl:21600}})));
  if(responses.some(response=>!response.ok))throw new Error("reference_rates_unavailable");
  const [fx,gold]=await Promise.all(responses.map(response=>response.json()));
  if(!Array.isArray(fx)||!fx.length||!Array.isArray(gold)||!gold.length)throw new Error("reference_rates_empty");
  const date=[...fx,...gold].map(item=>item.date).filter(Boolean).sort().at(-1)||"";
  const data={date,fx,gold,source:"Frankfurter",frequency:"daily_reference",fetchedAt:new Date().toISOString(),stale:false};
  try{await caches.default.put(key,new Response(JSON.stringify(data),{headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"public, max-age=259200","X-Content-Type-Options":"nosniff"}}));}catch(e){}
  return data;
 }catch(error){
  if(staleData)return {...staleData,stale:true,staleReason:"provider_unavailable",checkedAt:new Date().toISOString()};
  throw new Error("reference_rates_unavailable");
 }
}
function xml(value){return String(value??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&apos;");}
function rss(feed){
 const posts=(Array.isArray(feed?.posts)?feed.posts:[]).filter(p=>p&&p.status!=="Draft"&&p.status!=="Reserved").sort((a,b)=>Number(b.day||0)-Number(a.day||0));
 const items=posts.map(p=>{
  const d=new Date(p.publishedAt||"");
  const pub=Number.isNaN(d.getTime())?"":`<pubDate>${d.toUTCString()}</pubDate>`;
  const link="https://ceo-notes.pages.dev/post/"+encodeURIComponent(String(p.day||""));
  const taxonomy=[p.category,...(Array.isArray(p.tags)?p.tags:[])].filter(Boolean).map(tag=>`<category>${xml(tag)}</category>`).join("");
  return `<item><title>${xml(p.title)}</title><link>${xml(link)}</link><guid isPermaLink="false">ceo-notes-day-${xml(p.day)}</guid><description>${xml(p.article)}</description>${taxonomy}${pub}</item>`;
 }).join("");
 return `<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>CEO Notes</title><link>https://ceo-notes.pages.dev/</link><description>أفكار عملية عن القيادة والإدارة والعمل الذكي.</description><language>ar</language>${items}</channel></rss>`;
}
function sitemap(feed){
 const posts=(Array.isArray(feed?.posts)?feed.posts:[]).filter(p=>p&&p.status!=="Draft"&&p.status!=="Reserved");
 const urls=['<url><loc>https://ceo-notes.pages.dev/</loc></url>',...posts.map(p=>'<url><loc>https://ceo-notes.pages.dev/post/'+encodeURIComponent(String(p.day))+'</loc></url>')].join("");
 return '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+urls+'</urlset>';
}
function articleHtml(post){
 const title=xml((post.title||"CEO Notes")+" | CEO Notes");
 const description=xml(String(post.article||"").replace(/\s+/g," ").slice(0,155));
 const canonical="https://ceo-notes.pages.dev/post/"+encodeURIComponent(String(post.day));
 const image=typeof post.imageUrl==="string"&&post.imageUrl.startsWith("https://")?xml(post.imageUrl):"";
 const published=post.publishedAt&&!Number.isNaN(new Date(post.publishedAt).getTime())?xml(new Date(post.publishedAt).toISOString()):"";
 const section=xml(post.category||"");
 return HTML.replace(/<title>[\s\S]*?<\/title>/,'<title>'+title+'</title>')
  .replace(/<meta name="description" content="[^"]*">/,'<meta name="description" content="'+description+'">')
  .replace(/<meta property="og:type" content="[^"]*">/,'<meta property="og:type" content="article">')
  .replace(/<meta property="og:title" content="[^"]*">/,'<meta property="og:title" content="'+title+'">')
  .replace(/<meta property="og:description" content="[^"]*">/,'<meta property="og:description" content="'+description+'">')
  .replace(/<meta property="og:url" content="[^"]*">/,'<meta property="og:url" content="'+canonical+'">')
  .replace(/<meta property="og:image" content="[^"]*">/,'<meta property="og:image" content="'+image+'">')
  .replace(/<meta property="article:published_time" content="[^"]*">/,'<meta property="article:published_time" content="'+published+'">')
  .replace(/<meta property="article:section" content="[^"]*">/,'<meta property="article:section" content="'+section+'">')
  .replace(/<meta name="twitter:card" content="[^"]*">/,'<meta name="twitter:card" content="'+(image?"summary_large_image":"summary")+'">')
  .replace(/<meta name="twitter:title" content="[^"]*">/,'<meta name="twitter:title" content="'+title+'">')
  .replace(/<meta name="twitter:description" content="[^"]*">/,'<meta name="twitter:description" content="'+description+'">')
  .replace(/<meta name="twitter:image" content="[^"]*">/,'<meta name="twitter:image" content="'+image+'">')
  .replace(/<link rel="canonical" href="[^"]*">/,'<link rel="canonical" href="'+canonical+'">');
}
const XML_HEADERS={"Content-Type":"application/xml; charset=utf-8","Cache-Control":"public, max-age=300","X-Content-Type-Options":"nosniff"};
const HTML_HEADERS={"Content-Type":"text/html; charset=utf-8","Cache-Control":"public, max-age=60, s-maxage=300","X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin","X-Frame-Options":"DENY"};
export default {async fetch(request){
 const url=new URL(request.url);
 if(request.method!=="GET"&&request.method!=="HEAD")return new Response("Method Not Allowed",{status:405});
 if(url.pathname==="/radio.css")return new Response(request.method==="HEAD"?null:RADIO_CSS,{headers:{"Content-Type":"text/css; charset=utf-8","Cache-Control":"public, max-age=300","X-Content-Type-Options":"nosniff"}});
 if(url.pathname==="/radio.js")return new Response(request.method==="HEAD"?null:RADIO_JS,{headers:{"Content-Type":"application/javascript; charset=utf-8","Cache-Control":"public, max-age=300","X-Content-Type-Options":"nosniff"}});

 if(url.pathname==="/feed"){
  const data=await latestFeed(url.origin);
  return new Response(JSON.stringify(data),{headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"}});
 }
 if(url.pathname==="/markets"){
  try{
   const data=await marketData(url.origin),headers={"Content-Type":"application/json; charset=utf-8","Cache-Control":data.stale?"public, max-age=60":"public, max-age=300","X-Content-Type-Options":"nosniff","X-Data-Stale":String(Boolean(data.stale))};
   if(data.stale)headers.Warning='110 - "Response is stale"';
   return new Response(JSON.stringify(data),{headers});
  }catch(e){return new Response(JSON.stringify({error:"market_data_unavailable",message:"Daily reference rates are temporarily unavailable."}),{status:503,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"}});}
 }
 if(url.pathname==="/rss.xml")return new Response(rss(await latestFeed(url.origin)),{headers:XML_HEADERS});
 if(url.pathname==="/robots.txt")return new Response("User-agent: *\nAllow: /\nSitemap: https://ceo-notes.pages.dev/sitemap.xml\n",{headers:{"Content-Type":"text/plain; charset=utf-8","Cache-Control":"public, max-age=3600"}});
 if(url.pathname==="/sitemap.xml")return new Response(sitemap(await latestFeed(url.origin)),{headers:XML_HEADERS});
 const articleMatch=url.pathname.match(/^\/post\/(\d+)\/?$/);
 if(articleMatch){
  const feed=await latestFeed(url.origin),day=Number(articleMatch[1]);
  const post=(Array.isArray(feed.posts)?feed.posts:[]).find(p=>Number(p.day)===day&&p.status!=="Draft"&&p.status!=="Reserved");
  if(!post)return new Response("Article Not Found",{status:404,headers:{"Content-Type":"text/plain; charset=utf-8","X-Content-Type-Options":"nosniff"}});
  return new Response(request.method==="HEAD"?null:articleHtml(post),{headers:HTML_HEADERS});
 }
 if(url.pathname==="/"||url.pathname==="/index.html")return new Response(request.method==="HEAD"?null:HTML,{headers:HTML_HEADERS});
 if(url.pathname==="/posts.json")return new Response(POSTS,{headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"}});
 return new Response("Not Found",{status:404,headers:{"X-Content-Type-Options":"nosniff"}});
}};